function openJournal(chunks) {
  let iterator = null;
  let started = false;
  let closed = false;
  let finished = false;
  let sourceEOF = false;
  let returnPromise = null;

  let chunk = null;
  let offset = 0;
  let line = 1;
  let lineHasBytes = false;
  let parts = [];
  let decoder = new TextDecoder("utf-8");

  function done() {
    return { done: true, value: undefined };
  }

  function getIterator() {
    if (!started) {
      started = true;
      iterator = chunks[Symbol.asyncIterator]();
    }
    return iterator;
  }

  function returnIterator() {
    if (!iterator || sourceEOF) return Promise.resolve();

    if (!returnPromise) {
      try {
        const method = iterator.return;
        returnPromise =
          typeof method === "function"
            ? Promise.resolve(method.call(iterator))
            : Promise.resolve();
      } catch (error) {
        returnPromise = Promise.reject(error);
      }
    }

    return returnPromise;
  }

  async function stopAfterReadError(error) {
    finished = true;
    try {
      await returnIterator();
    } catch (_) {
      // The original read error takes precedence.
    }
    throw error;
  }

  function append(bytes) {
    if (bytes.length === 0) return;

    lineHasBytes = true;
    const text = decoder.decode(bytes, { stream: true });
    if (text) parts.push(text);
  }

  function finishLine(hadLineFeed) {
    const tail = decoder.decode();
    if (tail) parts.push(tail);

    let text = parts.length === 1 ? parts[0] : parts.join("");
    parts = [];
    decoder = new TextDecoder("utf-8");

    if (hadLineFeed && text.endsWith("\r")) {
      text = text.slice(0, -1);
    }

    lineHasBytes = false;

    if (text.trim().length === 0) return null;

    try {
      return { line, ok: true, value: JSON.parse(text) };
    } catch (_) {
      return { line, ok: false, text };
    }
  }

  async function next() {
    if (closed || finished) return done();

    while (true) {
      if (closed) {
        finished = true;
        return done();
      }

      if (chunk && offset < chunk.length) {
        let newline = offset;
        while (newline < chunk.length && chunk[newline] !== 10) newline++;

        append(chunk.subarray(offset, newline));
        offset = newline;

        if (newline < chunk.length) {
          offset++;
          const event = finishLine(true);
          line++;

          if (event) return { done: false, value: event };
          continue;
        }

        continue;
      }

      chunk = null;
      offset = 0;

      if (sourceEOF) {
        if (lineHasBytes) {
          const event = finishLine(false);
          finished = true;
          if (event) return { done: false, value: event };
        } else {
          finished = true;
        }
        return done();
      }

      let step;
      try {
        step = await getIterator().next();
      } catch (error) {
        return stopAfterReadError(error);
      }

      if (closed) {
        finished = true;
        try {
          await returnIterator();
        } catch (_) {}
        return done();
      }

      if (step.done) {
        sourceEOF = true;
      } else {
        chunk = step.value;
      }
    }
  }

  async function close() {
    if (closed) {
      if (returnPromise) await returnPromise;
      return;
    }

    closed = true;
    finished = true;

    if (iterator && !sourceEOF) {
      await returnIterator();
    }
  }

  return { next, close };
}
